mapper.select:
select pr.payroll_id, e.employee_no, e.name as employee_name, e.account_number, e.bank_name, d.department_name, p.position_name, max(case when pd.item_name_snapshot = '기본급' then pd.amount else 0 end) as basic_salary_amount, max(case when pd.item_name_snapshot = '식대' then pd.amount else 0 end) as meal_allowance_amount, max(case when pd.item_name_snapshot = '교통비' then pd.amount else 0 end) as transportation_allowance_amount, max(case when pd.item_name_snapshot = '직급수당' then pd.amount else 0 end) as position_allowance_amount, max(case when pd.item_name_snapshot = '직책수당' then pd.amount else 0 end) as responsibility_allowance_amount, sum(case when pd.item_name_snapshot != '기본급' then pd.amount else 0 end) as total_allowance_amount from payroll pr left join payroll_detail pd on pd.payroll_id = pr.payroll_id left join employee e on pr.employee_id = e.employee_id left join department d on d.department_id = e.department_id left join positions p on e.position_id = p.position_id where pr.payroll_year_month = #{yearMonth}
and e.name like concat('%', #{request.keyword}, '%')
and d.department_name = #{request.departmentName}
and p.position_name = #{request.positionName}
group by employee_no

mapper.update:

update payroll_detail pd
join payroll p
    on p.payroll_id = pd.payroll_id
set pd.amount =
    case
        pd.item_name_snapshot
    when '기본급' then #{basicSalary}
    when '식대' then #{mealAllowance}
    when '교통비' then #{transportationAllowance}
    when '직급수당' then #{responsibilityAllowance}
    when '직책수당' then #{dutyAllowance}
        else
            pd.amount
    END
where p.employee_id = #{employeeId}
    and p.payroll_year_month = #{payrollYearMonth}

mapper.select:
select count(*) from payroll
where employee_id = #{employeeId}
and payroll_year_month = #{payrollYearMonth}

select pr.payroll_id, e.employee_no, e.name as employee_name, d.department_name, pr.payment_date, pr.payroll_status_code, max(case when pd.item_name_snapshot = '기본급' then pd.amount else 0 end) as basic_salary_amount, max(case when pd.item_name_snapshot = '식대' then pd.amount else 0 end) as meal_allowance_amount, max(case when pd.item_name_snapshot = '교통비' then pd.amount else 0 end) as transportation_allowance_amount, max(case when pd.item_name_snapshot = '야근수당' then pd.amount else 0 end) as overtime_allowance_amount from payroll pr left join payroll_detail pd on pd.payroll_id = pr.payroll_id left join employee e on pr.employee_id = e.employee_id left join department d on d.department_id = e.department_id where pr.payroll_year_month = #{yearMonth}
and e.name like concat('%', #{request.keyword}, '%')
and d.department_name = #{request.departmentName}
group by pr.payroll_id, e.employee_no, e.name, d.department_name, pr.payment_date, pr.payroll_status_code
